def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_d = 0
    me_d = 0
    for a in opp:
        if a == 'D':
            opp_d += 1
    for a in me:
        if a == 'D':
            me_d += 1

    last_me, last_opp = history[-1]

    # Endgame: secure mutual cooperation or punish known defectors.
    if n >= 96:
        if opp_d * 3 < n:
            return 'C'
        return 'D'

    # Full last-8 window features, computed without repeated slicing where easy.
    start = n - 8
    if start < 0:
        start = 0
    recent_def = 0
    recent_len = n - start
    for i in range(start, n):
        if opp[i] == 'D':
            recent_def += 1

    # Track opponent cooperation/defection immediately after own actions.
    after_my_c_c = 0
    after_my_c_d = 0
    after_my_d_c = 0
    after_my_d_d = 0
    changes = 0
    same_opp = 0
    for i in range(1, n):
        pa = me[i - 1]
        b = opp[i]
        if pa == 'C':
            if b == 'C':
                after_my_c_c += 1
            else:
                after_my_c_d += 1
        else:
            if b == 'C':
                after_my_d_c += 1
            else:
                after_my_d_d += 1
        if opp[i] == opp[i - 1]:
            same_opp += 1
        else:
            changes += 1

    # Strong unconditional defector: minimize losses.
    if opp_d >= 4 and opp_d * 4 >= n * 3:
        if recent_def >= 6:
            return 'D'
        if last_opp == 'C' and rng.random() < 0.05:
            return 'C'
        return 'D'

    # Against very cooperative opponents, exploit carefully but avoid
    # triggering long punishment phases from conditional retaliators.
    if opp_d == 0:
        if n < 5:
            return 'C'
        if n > 20 and n < 90:
            if rng.random() < 0.12:
                return 'D'
        return 'C'

    # Detect strong reciprocity: opponent tends to copy our previous move.
    if n >= 8 and after_my_c_d + after_my_d_c > 0:
        mimic = after_my_c_c + after_my_d_d
        total = after_my_c_c + after_my_c_d + after_my_d_c + after_my_d_d
        if total > 0 and mimic * 10 >= total * 7:
            if last_opp == 'D':
                if last_me == 'D':
                    return 'C'
                return 'D'
            return 'C'

    # Alternating or highly patterned opponent: exploit with defection.
    if n >= 8 and changes * 10 >= (n - 1) * 8:
        return 'D'

    # If opponent heavily defected recently, punish, but occasionally forgive
    # to recover from accidental mutual punishment.
    if recent_len >= 4 and recent_def * 2 >= recent_len:
        if recent_def == recent_len:
            return 'D'
        if last_opp == 'C' and rng.random() < 0.3:
            return 'C'
        return 'D'

    # General moderate defector: retaliate quickly, with limited forgiveness.
    if opp_d >= 3 and opp_d * 2 > n:
        if last_opp == 'D':
            if recent_def >= 4:
                return 'D'
            if rng.random() < 0.18:
                return 'C'
            return 'D'
        if recent_def >= 3:
            return 'D'
        return 'C'

    # Core: generous tit-for-tat, biased toward restoring cooperation.
    if last_opp == 'D':
        if n >= 6:
            last6_d = 0
            s = n - 6
            for i in range(s, n):
                if opp[i] == 'D':
                    last6_d += 1
            if last6_d >= 5:
                return 'D'
        if rng.random() < 0.22:
            return 'C'
        return 'D'

    # Opponent cooperated last: cooperate, but if we have been defecting while
    # they remained cooperative, repair with a clear cooperative move.
    if last_opp == 'C':
        if n >= 10 and me_d > 0 and opp_d == 0:
            return 'C'
        return 'C'

    return 'C'
